      function stmap(st)
c Use this function to interpolate by means of
c   stnode_i=stmap(stnode_stored_i).
c Example (to be used below): tmp=log10(st)
      implicit none
      real*8 stmap,st,tmp
c
      tmp=st
      stmap=tmp
      return
      end
  
  
      function xmmap(xm)
c Use this function to interpolate by means of
c   xmnode_i=xmmap(xmnode_stored_i).
